syntax:
Template declaration and partial specialization:

```c++
template <typename T> struct MyTemplate {
  void myFunc() { /* ... */ }
};

template <typename T, typename U> struct MyTemplate<std::pair<T, U>> {
  void myFunc() { /* Specialized behavior */ }
};

template <typename T> struct MyTemplate<T*> {
  void myFunc() { /* Specialized behavior for pointers */}
};
```
